const D = { density: .5, crack: .45, energy: .6, speed: 1, warp: .35, scale: 1, hue: 30, x: .5, y: .5, style: 'stained', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp = (v,a,b) => Math.max(a, Math.min(b, v)), TAU = Math.PI*2;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat; S.lastBeat = K.beat;

// ---- coarse buffer (<=200 wide), cached on size ----
const BW = 168, BH = Math.max(72, Math.min(200, Math.round(BW * height / width)));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }

// ---- seed-deterministic drifting sites ----
const NS = Math.max(6, Math.round(8 + clp(P.density,0,1) * 36));   // 8..44 cells
if (S.seedUsed !== P.seed || S.nUsed !== NS) {
  S.seedUsed = P.seed; S.nUsed = NS;
  S.sx = []; S.sy = []; S.vx = []; S.vy = []; S.sh = []; S.sk = []; S.wp = [];
  for (let i = 0; i < NS; i++) {
    S.sx[i] = 0.06 + fr(i*1.3 + 3.1) * 0.88;
    S.sy[i] = 0.06 + fr(i*2.7 + 7.7) * 0.88;
    const ang = fr(i*5.1) * TAU, sp = 0.010 + 0.035 * fr(i*9.2);
    S.vx[i] = Math.cos(ang) * sp; S.vy[i] = Math.sin(ang) * sp;
    S.sh[i] = fr(i*3.9 + 1.1);    // cell hue scalar
    S.sk[i] = fr(i*11.3 + 2.2);   // per-plate value / tone jitter
    S.wp[i] = fr(i*6.7 + 0.5);    // wobble phase
  }
  S.lastT = null;
}

// integrate drift by real seconds (never re-phases; tolerate t0 reset)
if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
const dt = clp(K.t - S.lastT, 0, 0.05); S.lastT = K.t;
const en = clp(P.energy,0,1) * (0.45 + 0.7 * K.intensity);
const rate = (0.35 + 0.9 * en) * clp(P.speed, 0, 3);
// section dramaturgy: gentle gather/scatter breathing about the anchor
const radial = (Math.sin(K.t * 0.09) * 0.05 + (K.section % 2 ? 0.02 : -0.02)) * en;
for (let i = 0; i < NS; i++) {
  S.sx[i] += S.vx[i]*dt*rate + (S.sx[i]-P.x)*radial*dt*2.2;
  S.sy[i] += S.vy[i]*dt*rate + (S.sy[i]-P.y)*radial*dt*2.2;
  if (S.sx[i] < 0.03) { S.sx[i] = 0.03; S.vx[i] = Math.abs(S.vx[i]); } else if (S.sx[i] > 0.97) { S.sx[i] = 0.97; S.vx[i] = -Math.abs(S.vx[i]); }
  if (S.sy[i] < 0.03) { S.sy[i] = 0.03; S.vy[i] = Math.abs(S.vy[i]); } else if (S.sy[i] > 0.97) { S.sy[i] = 0.97; S.vy[i] = -Math.abs(S.vy[i]); }
}
// per-site continuous wobble (guarantees motion floor even at speed 0)
const wob = 0.010 + clp(P.warp,0,1) * 0.020;
const sxA = [], syA = [];
for (let i = 0; i < NS; i++) {
  sxA[i] = S.sx[i] + wob * Math.sin(K.t * (0.35 + S.wp[i]*0.6) + S.wp[i]*TAU);
  syA[i] = S.sy[i] + wob * Math.cos(K.t * (0.28 + S.sh[i]*0.5) + S.sh[i]*TAU);
}

const style = P.style;
const ar = width / height;
const sc = clp(P.scale, 0.5, 2.2);
const warpA = clp(P.warp,0,1) * 0.030;
const crackW = 0.006 + clp(P.crack,0,1) * 0.050;
const secHue = K.section * 22;
const hb = (P.hue + S.sh[0]*30 + secHue) % 360;
const expo = 0.50 + clp(P.energy,0,1) * 0.65 + K.intensity * 0.28 + A.rms * 0.5 + K.pulse * 0.08 + A.bass * 0.22;

// iq cosine palette (rgb 0..1), anchored on base hue
function pal(m) {
  const hr = hb / 360;
  const r = 0.5 + 0.5 * Math.cos(TAU * (m + hr + 0.00));
  const g = 0.5 + 0.5 * Math.cos(TAU * (m + hr + 0.33));
  const b = 0.5 + 0.5 * Math.cos(TAU * (m + hr + 0.66));
  return [r, g, b];
}

const g = S.g; g.loadPixels(); const px = g.pixels;
for (let j = 0; j < BH; j++) {
  const ny = j / BH;
  for (let i = 0; i < BW; i++) {
    const nx = i / BW;
    // zoom about anchor + organic domain-warp crinkle
    let qx = (nx - P.x) / sc + P.x;
    let qy = (ny - P.y) / sc + P.y;
    qx += warpA * Math.sin((qy * 7.3 + K.t * 0.20) * 2.1);
    qy += warpA * Math.cos((qx * 6.7 - K.t * 0.17) * 2.1);
    // nearest (F1) & second (F2) site
    let b1 = 1e9, b2 = 1e9, id1 = 0;
    for (let k = 0; k < NS; k++) {
      const dx = (qx - sxA[k]) * ar, dy = (qy - syA[k]);
      const d = dx*dx + dy*dy;
      if (d < b1) { b2 = b1; b1 = d; id1 = k; } else if (d < b2) { b2 = d; }
    }
    const F1 = Math.sqrt(b1), F2 = Math.sqrt(b2), gap = F2 - F1;
    const mh = S.sh[id1], vk = S.sk[id1];
    const cf = clp(1 - gap / crackW, 0, 1), cfs = cf * cf;   // 1 at crack, 0 in interior
    let r, gg, b;
    if (style === 'cracked-earth') {
      const warmv = 0.30 + vk * 0.32;
      const sun = 0.80 + 0.35 * expo;
      r = warmv * 1.55 * sun; gg = warmv * 1.02 * sun; b = warmv * 0.48 * sun;
      const near = clp(gap / (crackW * 4.5), 0, 1);         // 0 at crack .. 1 deep plate
      const shade = 0.42 + 0.58 * near;
      r *= shade; gg *= shade; b *= shade;
      r *= (1 - cfs * 0.90); gg *= (1 - cfs * 0.90); b *= (1 - cfs * 0.82);
    } else if (style === 'soap-foam') {
      const film = F1 * 4.6 + mh * 1.0 + K.t * 0.05;
      const c = pal(film);
      const lum = 0.52 + 0.34 * expo;
      r = (c[0]*0.62 + 0.38) * lum; gg = (c[1]*0.62 + 0.38) * lum; b = (c[2]*0.62 + 0.38) * lum;
      r += cfs * 0.55; gg += cfs * 0.55; b += cfs * 0.60;    // bright plateau borders
    } else if (style === 'glow') {
      const c = pal(mh * 1.0 + 0.08);
      const glv = (cfs * 1.25 + 0.05) * (0.65 + 0.6 * expo);
      r = c[0] * glv + 0.020; gg = c[1] * glv + 0.020; b = c[2] * glv + 0.045;   // neon veins on near-black
    } else if (style === 'blueprint') {
      const tone = 0.09 + vk * 0.08;
      r = 0.03 + tone * 0.16; gg = 0.11 + tone * 0.34; b = 0.30 + tone * 0.55;
      const line = cfs;
      r += line * 0.85; gg += line * 0.90; b += line * 1.00;                     // white cracks on blue
    } else { // stained (default): jewel cells + dark leading + bevel rim
      const c = pal(mh * 0.92 + 0.05);
      const sh = 0.34 + 0.52 * expo;
      r = c[0] * sh; gg = c[1] * sh; b = c[2] * sh;
      r *= (1 - cfs * 0.92); gg *= (1 - cfs * 0.92); b *= (1 - cfs * 0.92);       // dark lead
      const rim = clp(1 - Math.abs(gap - crackW * 1.7) / (crackW * 0.9), 0, 1) * 0.34;
      r += rim; gg += rim; b += rim;                                             // glass bevel highlight
    }
    const o = 4 * (j * BW + i);
    px[o]   = Math.max(0, Math.min(255, r  * 255));
    px[o+1] = Math.max(0, Math.min(255, gg * 255));
    px[o+2] = Math.max(0, Math.min(255, b  * 255));
    px[o+3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// faint treble sparkle on the crack network (partial, never full-frame flash; zero during validation)
if ((A.treble > 0.02 || A.rms > 0.02) && P.alpha > 5) {
  push(); blendMode(ADD); noStroke();
  const sp = (A.treble * 0.55 + A.rms * 0.35) * clp(P.energy,0,1);
  fill((hb + 40) % 360, 22, 100, sp * 16);
  rect(0, 0, width, height);
  blendMode(BLEND); pop();
}
